const chapters=[
['00–03 s','A cidade chama.','O personagem começa a correr assim que o participante toca na tela. Uma instrução breve apresenta os dois gestos.','Tocar para começar; experimentar o salto.','A câmera acompanha o personagem e apresenta a avenida.', '0% 0%','Início'],
['03–10 s','Uma pausa no calor.','Sol intenso, asfalto quente e pouca vegetação tornam o percurso mais desafiador. Uma área verde pode mudar essa experiência.','Pular obstáculos e tocar no ponto de ativação da árvore.','A copa se expande, uma sombra legível cobre o trajeto e o asfalto perde o tom quente. A mudança é visual; não depende de uma simulação térmica.', '0% 0%','Calor'],
['10–18 s','Quando a chuva chega.','O céu muda, a chuva se intensifica e a água ocupa os pontos vulneráveis da rua. O jogador antecipa obstáculos e procura passagens.','Pular obstáculos e deslizar entre faixas seguras.','Poças e reflexos aparecem nas áreas baixas; o caminho seguro permanece visível. Chuva e água nunca escondem a próxima decisão.', '100% 0%','Chuva'],
['18–23 s','Dois caminhos. Dois efeitos.','À esquerda, concreto e pouca absorção. À direita, uma rota com infraestrutura verde. A escolha é rápida; a resposta está no cenário.','Deslizar para escolher a rota.','O jardim de chuva recebe a água por uma abertura no meio-fio; o caminho elevado permanece livre. Na rota vulnerável, barreiras conduzem a um desvio seguro, sem atravessar água.', '100% 0%','Escolha'],
['23–30 s','Prevenir também é agir.','Na borda da cidade surgem vegetação seca, resíduos e focos de fogo. O personagem mantém distância e aciona uma resposta preparada.','Tocar no aviso de prevenção e acionar a brigada à distância; seguir pelo trecho isolado e seguro.','Profissionais controlam o foco e liberam uma passagem segura. Prevenção e resiliência somam pontos.', '0% 100%','Prevenção'],
['30–40 s','Uma cidade mais preparada.','De 30 a 35 s, árvores, sombra e drenagem transformam o percurso. De 35 a 40 s, o resultado mostra o impacto das escolhas.','Ver o resultado e tocar em “Novo desafio”, ou aguardar o reinício.','A resiliência e a pontuação resumem a jornada. Após 5 s, o protótipo volta à atração.', '100% 100%','Transformação']];
const timeline=document.querySelector('.timeline');chapters.forEach((c,i)=>{const b=document.createElement('button');b.setAttribute('role','tab');b.innerHTML=`<small>${c[0]}</small>${String(i+1).padStart(2,'0')} · ${c[6]}`;b.onclick=()=>selectChapter(i);timeline.append(b);});function selectChapter(i){const c=chapters[i];[...timeline.children].forEach((b,j)=>b.setAttribute('aria-selected',j===i));document.getElementById('chapter-time').textContent=c[0];document.getElementById('chapter-title').textContent=c[1];document.getElementById('chapter-description').textContent=c[2];document.getElementById('chapter-action').textContent=c[3];document.getElementById('chapter-effect').textContent=c[4];document.getElementById('chapter-art').style.backgroundImage=`url(assets/reference-${[0,2,3,3,4,5][i]}.png)`;document.getElementById('chapter-art').setAttribute('aria-label','Arte conceitual: '+c[6]);}selectChapter(1);
const assets=[
{name:'Brazil House · Low Poly',cat:'cidade',img:'brazil-v2.jpg',author:'BOHNEN',license:'GRÁTIS · CC BY 4.0',url:'https://sketchfab.com/3d-models/brazil-house-low-poly-9738b9a091d84d30aa0d88a4243e5863',why:'Casa brasileira com reboco, telhado inclinado e portão. Apoio para o fundo residencial da etapa de prevenção; não corresponde aos prédios modernos da avenida principal.',adapt:'Modelo individual, não um bairro completo. Criar variações de fachada e calçada; ajustar materiais. Crédito obrigatório: Brazil House - Low Poly, Bohnen, CC BY 4.0.',format:'715 triângulos · formatos disponíveis no download'},
{name:'Stylized Nature MegaKit',cat:'natureza',img:'nature-v2.jpg',author:'QUATERNIUS',license:'STANDARD GRÁTIS · CC0',url:'https://quaternius.com/packs/stylizednaturemegakit.html',why:'Folhagem texturizada, copas orgânicas, arbustos e gramíneas: uma aproximação muito melhor da vegetação rica das imagens.',adapt:'Selecionar o Standard gratuito: 68 assets na prévia oficial. Vento, shaders e projetos das edições pagas não devem ser presumidos incluídos. Sombra e crescimento serão preparados no jogo.',format:'FBX · OBJ · glTF'},
{name:'Ultimate Modular Men',cat:'personagem',img:'men-v3.jpg',author:'QUATERNIUS',license:'GRÁTIS · CC0',url:'https://quaternius.com/packs/ultimatemodularcharacters.html',why:'Proporções humanas, roupas modulares e rig humanoide. Base civil masculina para estudar o rig. As proporções adultas e angulares ainda diferem do jovem das referências.',adapt:'O autor anuncia 11 personagens e 24 animações. Adaptar proporções, rosto e cabelo cacheado; criar camiseta turquesa e mochila amarela. Validar corrida, salto e transições antes de integrar.',format:'FBX · OBJ · glTF · Blender'},
{name:'Downtown City MegaKit',cat:'cidade',img:'city-v2.jpg',author:'QUATERNIUS',license:'STANDARD GRÁTIS · CC0',url:'https://quaternius.com/packs/downtowncitymegakit.html',why:'Fachadas e janelas com mais detalhe para o fundo urbano. Opção secundária para complementar o bairro.',adapt:'Arquitetura norte-americana: exige adaptação para uma cidade brasileira. A prévia mostra o conjunto promocional; o Standard gratuito contém apenas parte do catálogo. Projetos e shaders da edição Source são pagos.',format:'Módulos 3D · FBX / glTF'},
{name:'Particle Pack',cat:'apoio',img:'particle-pack.png',author:'KENNEY',license:'GRÁTIS · CC0',url:'https://kenney.nl/assets/particle-pack',why:'Apoio discreto para faíscas e feedback. A identidade visual vem dos cenários, materiais e personagens selecionados acima.',adapt:'Texturas 2D para emissores 3D; fogo, chuva e feedback precisam de configuração própria.',format:'PNG · texturas 2D'},
{name:'Smoke Particles',cat:'apoio',img:'smoke-particles.png',author:'KENNEY',license:'GRÁTIS · CC0',url:'https://kenney.nl/assets/smoke-particles',why:'Fumaça suave para comunicar o foco de incêndio sem ocultar o percurso.',adapt:'Usar baixa opacidade e poucos emissores. Não inclui brigadistas nem sistema de combate ao fogo.',format:'PNG · texturas 2D'}];
function renderAssets(filter='all'){document.getElementById('asset-grid').innerHTML=assets.filter(a=>filter==='all'||a.cat===filter).map(a=>`<article class="asset-card"><img loading="lazy" src="assets/${a.img}" alt="Prévia oficial: ${a.name}"><div class="asset-content"><div class="asset-meta"><span>${a.author}</span><span>${a.license}</span></div><h3>${a.name}</h3><p>${a.why}</p><p class="usage"><b>Para usar no jogo:</b> ${a.adapt}</p><p>${a.format}</p><a href="${a.url}" target="_blank" rel="noopener">Ver asset e download oficial <span>↗</span></a></div></article>`).join('');}renderAssets();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderAssets(b.dataset.filter);});const dialog=document.getElementById('art-dialog');document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{const img=dialog.querySelector('img');img.src=b.dataset.art;img.alt=b.dataset.title;dialog.showModal();});document.getElementById('close-art').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};
